// ---------- 辅助函数 ----------
function xesLectureLabel(l) { return l.level + '级第' + l.no + '讲 ' + l.title; }
// 某讲次关联的盘古主题 (直接标注)
function xesPanguTopics(l) { return (l.pangu || []).map(id => (typeof panguNodeMap !== 'undefined' ? panguNodeMap[id] : null)).filter(Boolean); }
// 某盘古主题对应的学而思讲次 (反查)
function xesLecturesForPangu(panguId) { return xesLectures.filter(l => (l.pangu || []).includes(panguId)); }
// 某小学教材节点对应的学而思讲次 (反查)
function xesLecturesForElementary(elemId) { return xesLectures.filter(l => (l.elementary || []).includes(elemId)); }
